from pathlib import Path
import json
p=Path('.')
base='''@font-face{font-family:DM;src:url('assets/dm-sans-400.ttf')}@font-face{font-family:DM;src:url('assets/dm-sans-500.ttf');font-weight:500}@font-face{font-family:DM;src:url('assets/dm-sans-700.ttf');font-weight:700}*{box-sizing:border-box}#root{position:absolute;inset:0;width:1920px;height:1080px;color:#263D33;font-family:DM,sans-serif}.ground{position:absolute;inset:0;background:#F7F8F4}.top{position:absolute;left:96px;right:96px;top:54px;display:flex;align-items:center;justify-content:space-between;height:60px}.brand{display:flex;gap:14px;align-items:center;font-size:36px;font-weight:700;letter-spacing:-1.5px}.brand img{width:48px;height:48px}.chapter{font-size:20px;letter-spacing:3px;font-weight:500}.rule{position:absolute;top:132px;left:96px;right:96px;height:2px;background:#D4DDA4}.display{font-weight:500;letter-spacing:-5px;line-height:1.03;margin:0}.eyebrow{font-size:20px;letter-spacing:3px;font-weight:500}.muted{color:#62795D}.stage{position:absolute}.shot{position:absolute;display:block;object-fit:contain}.bottom-note{position:absolute;left:96px;top:860px;font-size:25px;line-height:1.45}.caption-clear{position:absolute;left:96px;right:96px;top:940px;height:2px;background:#D4DDA4}.image-border{border:2px solid #D4DDA4;border-radius:12px;overflow:hidden}.chip{display:inline-flex;align-items:center;gap:12px;padding:16px 24px;background:#EDF1E6;border-radius:8px;font-size:24px;font-weight:500}'''

def scene(n,name,duration,title,html,css,js,dark=False):
 header=f'<div class="top"><div class="brand"><img src="assets/brand.svg"/>statewise.</div><div class="chapter">0{n} / {title}</div></div><div class="rule"></div>'
 content=f'<div id="root" data-composition-id="{n:02d}-{name}" data-width="1920" data-height="1080" data-duration="{duration}"><div class="ground clip" data-start="0" data-duration="{duration}" data-track-index="0"></div>{header}{html}<div class="caption-clear"></div></div>'
 darkcss='.ground{background:#263D33}#root{color:#F7F8F4}.muted{color:#D4DDA4}.rule,.caption-clear{background:#62795D}' if dark else ''
 doc=f'<template>\n<style>{base}{darkcss}{css}</style>\n{content}\n<script>const tl=gsap.timeline({{paused:true}});{js}\nwindow.__timelines["{n:02d}-{name}"]=tl;</script>\n</template>'
 (p/f'compositions/frames/{n:02d}-{name}.html').write_text(doc)
scene(1,'discover',10.2,'EXPLORE', '''<div class="stage headline"><div class="eyebrow">A LITTLE CURIOSITY GOES A LONG WAY</div><div class="number display">50<span>states.</span></div><h1 class="display promise">Start with one.</h1></div><div class="stage map-stage"><img class="map-shot" src="assets/map-panel.png"/></div><div class="bottom-note"><span class="chip">Explore the map</span><span class="small-note">Your next discovery is a tap away.</span></div>''', '''.headline{left:96px;top:216px;width:660px}.headline .eyebrow{font-size:17px;letter-spacing:2px;position:absolute;left:0;top:0}.number{position:absolute;left:0;top:70px;font-size:260px;letter-spacing:-15px;margin-top:0;line-height:.95}.number span{font-size:88px;letter-spacing:-4px;display:block;margin-top:6px}.promise{position:absolute;left:0;top:515px;font-size:74px;margin-top:0;color:#335D45}.map-stage{left:780px;top:220px;width:1040px;height:615px;display:flex;align-items:center}.map-shot{width:100%;height:auto;border:2px solid #D4DDA4;border-radius:14px}.bottom-note{display:flex;gap:24px;align-items:center}.small-note{font-size:24px;color:#62795D}''', '''tl.fromTo('.number',{y:35,opacity:0},{y:0,opacity:1,duration:.7,ease:'power3.out'},.05);tl.fromTo('.map-stage',{x:90,opacity:0},{x:0,opacity:1,duration:1,ease:'power3.out'},1.3);tl.fromTo('.promise',{y:28,opacity:0},{y:0,opacity:1,duration:.7,ease:'power3.out'},2.6);tl.fromTo('.bottom-note',{y:20,opacity:0},{y:0,opacity:1,duration:.6},5);tl.to('.map-shot',{scale:1.035,transformOrigin:'50% 55%',duration:1.2,ease:'power2.inOut'},6.2);''')
scene(2,'learn',9.8,'DISCOVER', '''<div class="stage headline"><div class="eyebrow">CALIFORNIA / THE GOLDEN STATE</div><h1 class="display">A state.<span>A story.</span></h1></div><div class="stage facts"><div class="fact fact-one"><small>CAPITAL</small><strong>Sacramento</strong></div><div class="fact fact-two"><small>STATEHOOD</small><strong>1850</strong></div><div class="fact fact-three"><small>A LITTLE STATE OF WONDER</small><p>Mount Whitney to Death Valley.<br/>The highest and lowest points<br/>in the contiguous U.S.</p></div></div><div class="stage card-stage"><img class="shot card before" src="assets/california.png"/><img class="shot card after" src="assets/california-learned.png"/></div><div class="stage saved chip">✓ &nbsp; Added to your discoveries</div>''', '''.headline{left:96px;top:190px;width:800px}.headline h1{font-size:116px;margin-top:24px}.headline h1 span{display:block;color:#335D45}.facts{left:96px;top:505px;width:860px;display:grid;grid-template-columns:1fr 1fr;gap:30px}.fact{border-top:2px solid #D4DDA4;padding-top:18px}.fact small{font-size:17px;letter-spacing:2px}.fact strong{display:block;font-size:57px;letter-spacing:-2px;font-weight:500;margin-top:12px}.fact-three{grid-column:1/3}.fact p{font-size:29px;line-height:1.35;margin:12px 0 0}.card-stage{left:1130px;top:168px;width:510px;height:730px}.card{width:510px;height:730px;object-position:top}.saved{left:1122px;top:846px;background:#335D45;color:#F7F8F4;font-size:23px}''', '''tl.fromTo('.card-stage',{y:35,opacity:0},{y:0,opacity:1,duration:.8,ease:'power3.out'},0);tl.fromTo('.headline',{y:20,opacity:0},{y:0,opacity:1,duration:.6},0);tl.fromTo('.fact-one',{y:18,opacity:0},{y:0,opacity:1,duration:.5},1.5);tl.fromTo('.fact-two',{y:18,opacity:0},{y:0,opacity:1,duration:.5},2.5);tl.fromTo('.fact-three',{y:18,opacity:0},{y:0,opacity:1,duration:.5},4.1);tl.fromTo('.after',{opacity:0},{opacity:1,duration:.25},7.2);tl.fromTo('.saved',{y:16,opacity:0},{y:0,opacity:1,duration:.5,ease:'power3.out'},7.35);''')
scene(3,'practice',10.92,'TRY IT', '''<div class="stage headline"><div class="eyebrow">THE MAP CHALLENGE</div><h1 class="display">A wrong guess.<span>A better<br/>memory.</span></h1></div><div class="stage explanation"><div class="step one"><span>01</span><p>Take a guess.</p></div><div class="step two"><span>02</span><p>See the correct outline.</p></div><div class="step three"><span>03</span><p>Try the next one.</p></div></div><div class="stage quiz-stage"><img class="shot question" src="assets/quiz-question.png"/><img class="shot wrong" src="assets/quiz-wrong.png"/><img class="shot correct" src="assets/quiz-correct.png"/></div>''', '''.headline{left:96px;top:205px;width:890px}.headline h1{font-size:106px;margin-top:30px;line-height:1.05;letter-spacing:-5px}.headline h1 span{display:block;color:#D4DDA4}.explanation{left:96px;top:655px;width:780px}.step{display:flex;gap:23px;align-items:center;height:65px}.step span{font-size:19px;letter-spacing:2px;color:#D4DDA4}.step p{font-size:30px;margin:0}.quiz-stage{left:1100px;top:154px;width:655px;height:752px}.quiz-stage .shot{width:655px;height:auto;max-height:752px;object-position:top;left:0;top:0;border-radius:14px}''', '''tl.fromTo('.headline',{y:25,opacity:0},{y:0,opacity:1,duration:.6,ease:'power3.out'},0);tl.fromTo('.quiz-stage',{x:40,opacity:0},{x:0,opacity:1,duration:.7,ease:'power3.out'},.1);tl.fromTo('.one',{opacity:0,y:12},{opacity:1,y:0,duration:.4},.7);tl.fromTo('.wrong',{opacity:0},{opacity:1,duration:.16},2.4);tl.fromTo('.two',{opacity:0,y:12},{opacity:1,y:0,duration:.4},4.8);tl.fromTo('.correct',{opacity:0},{opacity:1,duration:.16},8.0);tl.fromTo('.three',{opacity:0,y:12},{opacity:1,y:0,duration:.4},8.1);''',True)
scene(4,'remember',10.2,'KEEP GOING', '''<div class="stage headline"><div class="eyebrow">LOCATIONS. CAPITALS. NICKNAMES.</div><h1 class="display">A little practice.<span>A lot remembered.</span></h1></div><div class="stage choices"><img src="assets/practice-options.png"/></div><div class="stage progress"><img src="assets/progress.png"/></div><div class="stage phone"><div class="phone-screen"><img src="assets/mobile.png"/></div></div><div class="stage cta"><p>Learn one state today.</p><div>h3manth.com/fun/statewise</div></div>''', '''.headline{left:96px;top:190px;width:1190px}.headline h1{font-size:89px;margin-top:26px;letter-spacing:-4px}.headline h1 span{display:block;color:#335D45}.choices{left:96px;top:455px;width:1100px}.choices img{width:1100px;display:block}.progress{left:96px;top:452px;width:1100px}.progress img{width:1100px;display:block}.phone{left:1370px;top:174px;width:320px;height:694px;padding:8px;border:3px solid #263D33;border-radius:38px;background:#263D33}.phone-screen{border-radius:28px;overflow:hidden;height:100%;width:100%}.phone img{display:block;width:100%;height:100%;object-fit:cover;object-position:top}.cta{left:96px;top:745px}.cta p{font-size:29px;margin:0 0 18px}.cta div{font-size:49px;font-weight:500;letter-spacing:-1.5px;padding-bottom:12px;border-bottom:3px solid #335D45}''', '''tl.fromTo('.headline',{y:20,opacity:0},{y:0,opacity:1,duration:.6},0);tl.fromTo('.choices',{y:24,opacity:0},{y:0,opacity:1,duration:.6},.3);tl.fromTo('.progress',{opacity:0},{opacity:1,duration:.25},3.1);tl.to('.choices',{opacity:0,duration:.2},3.1);tl.fromTo('.phone',{x:60,opacity:0},{x:0,opacity:1,duration:.8,ease:'power3.out'},4.5);tl.fromTo('.cta',{y:20,opacity:0},{y:0,opacity:1,duration:.6},6.5);''')
# The storyboard statuses are orchestrator-owned.
